WITH matched_keys AS (SELECT device, id FROM sessions EXCEPT SELECT device, id FROM sessions WHERE customer_id = 25), verified AS (SELECT s.* FROM sessions s INNER JOIN matched_keys k ON s.device = k.device AND s.id = k.id) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, device, MIN(started_at) AS first_started_at, COUNT(CASE WHEN country = 'JP' THEN 1 END) AS jp_count, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(browser = 'Chrome') AS chrome_events, MAX(started_at) AS last_seen, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', started_at) ORDER BY COUNT(CASE WHEN country = 'JP' THEN 1 END) DESC) AS jp_count_dense_rank FROM verified GROUP BY DATE_TRUNC('QUARTER', started_at), device HAVING COUNT_IF(browser = 'Chrome') < 1000
